#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=3
CHECK_STARTUP=false
ALLOW_LIVE=false
case "${1:-}" in
  '') ;;
  --check-startup) CHECK_STARTUP=true ;;
  --allow-live) ALLOW_LIVE=true ;;
  *) printf 'Usage: bash tools/harness-eval-terminal.sh [--check-startup | --allow-live]\n' >&2; exit 2 ;;
esac
export CHECK_STARTUP
# Never inherit xtrace when handling a credential; never consult a local .env.
set +x
ENV_FILE=/dev/null
stage "Check isolated harness-eval profile"
say "Connectivity trial only; not a paired baseline or a quality/cost evaluation."
say "No installation, profile edits, permission changes, or web profile writes."
pause "Press Enter to check prerequisites (Ctrl-C cancels)."
if ! command -v node >/dev/null || ! command -v dsh >/dev/null; then
  warn "Missing prerequisite: node and dsh must already be installed." >&2
  exit 2
fi
if ! node --input-type=module <<'NODE'
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
try {
  const home = path.resolve(process.env.DSH_HOME || path.join(os.homedir(), '.dsh'));
  const profiles = fs.realpathSync(path.join(home, 'profiles'));
  const dir = path.join(profiles, 'harness-eval');
  if (fs.realpathSync(dir) !== dir) throw Error();
  for (const name of ['package.json', 'cordis.yml', 'cordis.patch.yml']) {
    const file = path.join(dir, name);
    if (!fs.lstatSync(file).isFile()) throw Error();
  }
  if (!fs.statSync(path.join(dir, 'node_modules')).isDirectory()) throw Error();
  const pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8'));
  const bundles = pkg.dsh?.profile?.bundles;
  if (!Array.isArray(bundles) || bundles.length !== 2 ||
      bundles[0] !== '@deepseek-ai/dsh-base' || bundles[1] !== '@deepseek-ai/dsh-headless') throw Error();
  // Empty cordis.yml is valid. Do not evaluate YAML/!!js or dump config/keys.
  const patch = fs.readFileSync(path.join(dir, 'cordis.patch.yml'), 'utf8');
  if (!/^\s+apiKeyEnv:\s*OR_API_KEY\s*$/m.test(patch) ||
      !/^\s+mode:\s*read-only\s*$/m.test(patch) ||
      /danger-full-access|workspace-write/.test(patch)) throw Error();
} catch {
  console.error('Profile prerequisite failed: require a real isolated harness-eval directory, installed node_modules, base + headless bundles, and a reviewed patch using OR_API_KEY and read-only policy. No DSH invoked.');
  process.exitCode = 2;
}
NODE
then
  exit 2
fi
# A process timeout is not a token budget, and one spawn is not zero retries.
# The installed provider defaults to five retries when retryPolicy is omitted.
# Regex matches cannot prove arbitrary layered YAML is safe; live trials require
# explicit opt-in as well as the hidden-key and one-trial confirmation below.
if [[ "$CHECK_STARTUP" != true && "$ALLOW_LIVE" != true ]]; then
  warn "Live trial blocked without --allow-live: budget <=4096 output tokens and zero automatic retries cannot be safely verified. No credential requested or DSH invoked; --check-startup remains available offline." >&2
  exit 2
fi
say "Profile checks passed. These checks are not a full YAML/plugin security audit."
warn "Continue only if you reviewed this profile: no tools, extra plugins, embedded credentials, or unsafe !!js."
say "Only the isolated profile is copied; home patches and .env files are not used."

stage "Hidden key and explicit one-trial consent"
if [[ "$CHECK_STARTUP" == true ]]; then
  TRIAL_KEY=''
  say "Offline startup check: no credential and no model task."
else
ask_secret TRIAL_KEY "Paste the OmniRoute API key (OR_API_KEY; memory only, never saved):"
if [[ -z "$TRIAL_KEY" ]] || ! confirm "Invoke DSH exactly ONCE, possibly incurring API cost?"; then
  unset TRIAL_KEY
  say "Cancelled; DSH was not invoked."
  exit 0
fi
fi
stage "One connectivity trial and sanitized log"
# Environment transport only: the key is never a command argument or file.
export TRIAL_KEY
set +e
node --input-type=module <<'NODE'
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
const key = process.env.TRIAL_KEY;
const startupOnly = process.env.CHECK_STARTUP === 'true';
delete process.env.TRIAL_KEY;
let temporary;
let status = 1;
try {
  const home = path.resolve(process.env.DSH_HOME || path.join(os.homedir(), '.dsh'));
  const profile = path.join(home, 'profiles/harness-eval');
  temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'harness-eval-trial-'));
  fs.chmodSync(temporary, 0o700);
  const trialHome = path.join(temporary, 'home');
  const trialProfile = path.join(trialHome, 'profiles/harness-eval');
  const workspace = path.join(temporary, 'workspace');
  fs.mkdirSync(trialProfile, { recursive: true });
  fs.mkdirSync(workspace);
  for (const name of ['package.json', 'cordis.yml', 'cordis.patch.yml']) {
    fs.copyFileSync(path.join(profile, name), path.join(trialProfile, name));
  }
  // DSH routes host peers by the importing module's real profile location.
   // An external symlink escapes this temporary profile and breaks that routing.
   fs.cpSync(fs.realpathSync(path.join(profile, 'node_modules')), path.join(trialProfile, 'node_modules'), { recursive: true, dereference: true });
  const logDir = path.resolve(process.env.HARNESS_EVAL_LOG_DIR || 'vibe-analysis/harness-eval-terminal');
  fs.mkdirSync(logDir, { recursive: true, mode: 0o700 });
  const log = path.join(logDir, `connectivity-${Date.now()}-${process.pid}.json`);
  // No inherited credentials, .env, DSH_HOME overrides or home-level patches.
  // PATH remains the public test seam and chooses the installed dsh command.
  const env = { PATH: process.env.PATH, HOME: temporary, DSH_HOME: trialHome,
    OR_API_KEY: key, TERM: 'dumb' };
  if (startupOnly) delete env.OR_API_KEY;
  env.DSH_TELEMETRY_DISABLED = '1';
  const args = ['--profile', 'harness-eval', '--json'];
  if (!startupOnly) args.push('Reply exactly HARNESS_EVAL_CONNECTIVITY_OK. Do not use tools or modify files.');
  const result = spawnSync('dsh', args,
    { cwd: workspace, env, input: '', timeout: 60000, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 });
  const exitCode = result.status ?? (result.signal ? 128 + (os.constants.signals[result.signal] || 1) : 1);
  // Empty stdin fails only after loader settlement, before model selection/agent creation.
  const startupVerified = startupOnly && !result.error && exitCode === 1 &&
    String(result.stderr).includes('a task is required, for example:') &&
    !/startup failed|Failed plugins/.test(String(result.stderr));
  status = startupOnly ? (startupVerified ? 0 : 1) : exitCode;
  const sanitize = text => {
    let value = String(text || '');
    if (key) value = value.split(key).join('[REDACTED]')
      .split(JSON.stringify(key).slice(1, -1)).join('[REDACTED]');
    return value.replace(/\bBearer\s+[^\s"']+/gi, 'Bearer [REDACTED]');
  };
  const report = { kind: startupOnly ? 'startup-only' : 'connectivity-only', exitCode, signal: result.signal,
    startupVerified, captureError: result.error ? result.error.code : null,
    stdout: sanitize(result.stdout), stderr: sanitize(result.stderr) };
  fs.writeFileSync(log, JSON.stringify(report) + '\n', { flag: 'wx', mode: 0o600 });
  console.log(`Sanitized ${startupOnly ? 'startup' : 'connectivity'} log: ${log}`);
  if (startupOnly) console.log(`Startup activation: ${startupVerified ? 'PASS' : 'FAIL'}; no model task submitted.`);
  console.log(`DSH exit code: ${exitCode}; no baseline or model quality claim.`);
} catch {
  console.error('Trial could not complete safely; no raw diagnostics printed.');
} finally {
  // The target is the exact private mkdtemp result, not user-supplied input.
  if (temporary && temporary.startsWith(path.join(os.tmpdir(), 'harness-eval-trial-'))) {
    fs.rmSync(temporary, { recursive: true, force: true });
  }
}
process.exitCode = status;
NODE
trial_status=$?
unset TRIAL_KEY
exit "$trial_status"
